<script setup>import AdminShell from '../../components/AdminShell.vue';import StatusBadge from '../../components/StatusBadge.vue';import {changes} from '../../api/mock';</script>
<template><AdminShell><template #title>工程变更</template><div class="heading"><div><p>ENGINEERING CHANGE CONTROL</p><h1>工程变更中心</h1><span>从变更申请、影响分析到实施验证的闭环控制</span></div><button class="btn primary">＋ 发起工程变更</button></div>
 <section class="change-flow"><div><small>01</small><span>草稿</span><b>3</b><i>→</i></div><div><small>02</small><span>评审中</span><b>5</b><i>→</i></div><div><small>03</small><span>待实施</span><b>4</b><i>→</i></div><div><small>04</small><span>验证中</span><b>6</b><i>→</i></div><div><small>05</small><span>本月已关闭</span><b>12</b></div><aside><span>按期关闭率</span><b>91.7%</b><small>目标 95%</small></aside></section>
 <section class="panel"><div class="toolbar"><div class="tabs"><button class="active">全部 <b>18</b></button><button>我的待办 <b>6</b></button><button>高风险 <b>4</b></button><button>即将逾期 <b>2</b></button></div><div><label>⌕ <input placeholder="搜索变更单"/></label><button>筛选 ⌄</button></div></div><table class="change-table"><thead><tr><th>变更单号 / 标题</th><th>关联产品</th><th>变更类型</th><th>风险</th><th>负责人</th><th>截止日期</th><th>当前状态</th><th></th></tr></thead><tbody><tr v-for="(c,i) in changes" :key="c.no"><td><b>{{c.no}}</b><small>{{c.title}}</small></td><td><span class="model-chip">{{c.product}}</span></td><td>{{c.type}}</td><td><StatusBadge :value="c.risk+'风险'"/></td><td><span class="avatar">{{c.owner[0]}}</span>{{c.owner}}</td><td :class="i===3?'overdue':''">{{c.due}}<small v-if="i===3">已逾期 1 天</small></td><td><StatusBadge :value="c.status"/></td><td>•••</td></tr></tbody></table><div class="table-note"><span>显示 1–4，共 18 条记录</span><div><button>‹</button><button class="active">1</button><button>2</button><button>3</button><button>›</button></div></div></section>
 </AdminShell></template>
